preConditionHook:
// EVERY one of the last spikeBars bar pairs overlaps the earlier bar by at
// most overlapFraction of THAT bar's range -- Brooks's thin, one-sided
// breakout area.
//
// EL: countif(minlist(high, high[1]) - maxlist(low, low[1]) <=
// overlapFraction * (high[1] - low[1]), spikeBars), and the count must equal
// the window. countif counts bars 0..N-1 including the current bar, and the
// counted condition is a true SERIES -- at position k its offsets shift, so it
// tests bar k against bar k + 1 (EL_FEATURES `countif`, VERIFIED; the
// frozen-offset model was refuted). The loop below reproduces that index for
// index.
//
// maxlist/minlist select among raw highs and lows -- tick-grid price operands,
// which is exactly the scope their ACCEPTED row allows -- so plain comparisons
// stand in for them here.
//
// Multiplied form, so a zero-range earlier bar cannot divide by zero and no
// epsilon is needed. A gap makes pairOverlap negative and the pair passes,
// which is the intent: a gap is the thinnest area there is.
//
// NOT the negation of OverlappingBarRun: negating an all-pairs conjunction
// gives "at least one pair overlaps little", not "every pair overlaps little",
// so no per-placement toggle reaches this from that rule. Also not
// AverageBarOverlap, which is a MEAN -- one wide pair fails this test while
// barely moving that one.
thinCount = 0.0;
for (int k = 0; k < (int)spikeBars; ++k) {
    pairTop = high[k];
    if (high[k + 1] < pairTop) pairTop = high[k + 1];
    pairBottom = low[k];
    if (low[k + 1] > pairBottom) pairBottom = low[k + 1];
    pairOverlap = pairTop - pairBottom;
    if (el_le(pairOverlap, overlapFraction * (high[k + 1] - low[k + 1]))) {
        thinCount += 1;
    }
}
